import java.io.*;
import java.util.*;

public class Main {
    static long modPow(long a, long e, long mod) {
        long r = 1 % mod;
        a %= mod;
        while (e > 0) {
            if ((e & 1) == 1) r = (r * a) % mod;
            a = (a * a) % mod;
            e >>= 1;
        }
        return r;
    }

    static long modInverse(long a, long mod) {
        return modPow(a, mod - 2, mod);
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long a = Long.parseLong(st.nextToken());
        long b = Long.parseLong(st.nextToken());
        int p = Integer.parseInt(st.nextToken());
        long x = Long.parseLong(st.nextToken());

        int mod = p;
        long invA = modInverse(a % mod, mod);

        long[] powA = new long[p];
        long[] invPowA = new long[p];
        powA[0] = 1;
        for (int i = 1; i < p; i++) {
            powA[i] = (powA[i - 1] * a) % mod;
        }
        invPowA[0] = 1;
        for (int i = 1; i < p; i++) {
            invPowA[i] = (invPowA[i - 1] * invA) % mod;
        }

        long[] f = new long[p];
        for (int k = 0; k < p; k++) {
            long val = (b * invPowA[k]) % mod;
            long fk = (val * modInverse(k + 1, mod)) % mod;
            f[k] = fk;
        }

        long ans = 0;
        long cycles = x / (p - 1);
        long rem = x % (p - 1);

        for (int k = 0; k < p; k++) {
            long fk = f[k];
            if (fk == 0) continue;
            long cnt = cycles;
            long t = fk - 1;
            if (t <= rem) cnt++;
            ans += cnt;
        }

        System.out.println(ans);
    }
}

