public class Main {
    static long modPow(long a, long e, long mod) {
        long r = 1 % mod;
        a %= mod;
        while (e > 0) {
            if ((e & 1) == 1) r = (r * a) % mod;
            a = (a * a) % mod;
            e >>= 1;
        }
        return r;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long a = Long.parseLong(st.nextToken());
        long b = Long.parseLong(st.nextToken());
        int p = Integer.parseInt(st.nextToken());
        long x = Long.parseLong(st.nextToken());

        int phi = p - 1;
        long invA = modPow(a, phi - 1, p); // a^(p-2) mod p

        long ans = 0;
        long cur = 1; // a^0
        for (int k = 0; k < phi; k++) {
            long n0 = (long) k * phi + 1;
            if (n0 > x) break;

            long rhs = (b * modPow(cur, phi - 1, p)) % p; // b * (a^k)^{-1}
            long t = rhs;
            if (t == 0) {
                // n ≡ 0 (mod p), but n0 ≡ 1 (mod p), so no solution in this progression
            } else {
                long invT = modPow(t, p - 2, p);
                long n = (invT * p) % (long) (p * 1L); // placeholder, we only need n mod p
                // Actually n ≡ invT (mod p)
                long nModP = invT;

                long delta = (nModP - n0) % p;
                if (delta < 0) delta += p;
                long step = (long) p * phi;
                long first = n0 + delta;
                if (first <= x) {
                    long cnt = (x - first) / step + 1;
                    ans += cnt;
                }
            }

            cur = (cur * a) % p;
        }

        System.out.println(ans);
    }
}

