        long invA = modInv(a % p, p);

        long[] powA = new long[p];
        long[] invPowA = new long[p];
        powA[0] = 1;
        for (int i = 1; i < p; i++) {
            powA[i] = (powA[i - 1] * a) % p;
        }
        invPowA[0] = 1;
        long invAmod = invA % p;
        for (int i = 1; i < p; i++) {
            invPowA[i] = (invPowA[i - 1] * invAmod) % p;
        }

        int[] cnt = new int[p];
        Arrays.fill(cnt, 0);

        long fullBlocks = x / phi;
        long rem = x % phi;

        for (int k = 0; k < p; k++) {
            long val = (b * invPowA[k]) % p;
            int n0 = (int) val;
            if (n0 == 0) continue;
            long t = n0 - k;
            long m;
            if (t <= 0) {
                long need = (-t + p - 1) / p;
                m = need;
            } else {
                m = 0;
            }
            long maxM = (phi - k - n0) / p;
            if (maxM < m) continue;
            long count = maxM - m + 1;
            if (count <= 0) continue;
            cnt[k] += count;
        }

        long ans = 0;
        for (int k = 0; k < p; k++) {
            long c = cnt[k];
            if (c == 0) continue;
            long total = fullBlocks * c;
            long limit = rem;
            long maxT = limit;
            long firstT = k;
            if (firstT > maxT) {
                ans += total;
                continue;
            }
            long extra = (maxT - firstT) / p + 1;
            if (extra < 0) extra = 0;
            if (extra > c) extra = c;
            total += extra;
            ans += total;
        }

        System.out.println(ans);
    }
}

