        int phi = p - 1;
        long[] inv = new long[p];
        inv[1] = 1;
        for (int i = 2; i < p; i++) {
            inv[i] = (p - (p / i) * inv[p % i] % p) % p;
        }

        long[] powA = new long[phi + 1];
        powA[0] = 1 % p;
        for (int i = 1; i <= phi; i++) {
            powA[i] = (powA[i - 1] * a) % p;
        }

