            long cnt = (x - first) / (p * (long) phi) + 1;
            ans += cnt;
        }

        System.out.println(ans);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static long modPow(long a, long e, long mod) {
        long r = 1 % mod;
        a %= mod;
        while (e > 0) {
            if ((e & 1) == 1) r = (r * a) % mod;
            a = (a * a) % mod;
            e >>= 1;
        }
        return r;
    }

    static long modInv(long a, long mod) {
        return modPow(a, mod - 2, mod);
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long a = Long.parseLong(st.nextToken());
        long b = Long.parseLong(st.nextToken());
        int p = Integer.parseInt(st.nextToken());
        long x = Long.parseLong(st.nextToken());

        int phi = p - 1;
        long invA = modInv(a % p, p);

        // precompute invA^k
        long[] invPow = new long[phi];
        invPow[0] = 1;
        for (int i = 1; i < phi; i++) {
            invPow[i] = (invPow[i - 1] * invA) % p;
        }

        long ans = 0;

        // For each k in [0, phi-1], solve n * a^n ≡ b (mod p)
        // => n ≡ b * (a^n)^(-1) (mod p)
        // Let n = k + t*(p-1), then a^n = a^k (since a^{p-1} ≡ 1)
        // So for fixed k, we need n ≡ c (mod p), where c = b * (a^k)^(-1) mod p
        // and n ≡ k (mod p-1). Count n in [1, x].
        for (int k = 0; k < phi; k++) {
            long ak = modPow(a, k, p);
            long invAk = modInv(ak, p);
            long c = (b % p) * invAk % p;

            // Solve system:
            // n ≡ k (mod phi)
            // n ≡ c (mod p)
            // Use CRT since gcd(phi, p) = 1 (p is prime, phi = p-1)
            long m1 = phi;
            long m2 = p;
            long diff = (c - k) % m2;
            if (diff < 0) diff += m2;

            // m1 * t ≡ diff (mod m2)
            // t ≡ diff * inv(m1) (mod m2)
            long invM1 = modInv(m1 % m2, m2);
            long t = (diff * invM1) % m2;

            long n0 = k + t * (long) m1; // minimal non-negative solution

            if (n0 == 0) n0 += (long) m1 * m2; // ensure positive

            if (n0 > x) continue;

            long step = (long) m1 * m2; // lcm since coprime
            long cnt = 1 + (x - n0) / step;
            ans += cnt;
        }

        System.out.println(ans);
    }
}
